from pysat.solvers import Cadical153, Glucose3, Minisat22
N=21; M=39
edges=[]
for g in range(7):
    base=3*g
    edges += [(base+0,base+1),(base+0,base+2),(base+1,base+2)]
for g in range(6):
    for i in range(3):
        edges.append((3*g+i,3*(g+1)+i))
E=len(edges)
# vars
var=1
x=[[0]*(M+1) for _ in range(N)]
for v in range(N):
    for l in range(M+1):
        x[v][l]=var; var+=1
z=[[0]*(M+1) for _ in range(E)] # d 1..39
for e in range(E):
    for d in range(1,M+1):
        z[e][d]=var; var+=1
print('vars', var-1)
solver=Cadical153()
clauses=0
def add(c):
    global clauses
    solver.add_clause(c); clauses+=1
# exactly one label per vertex
for v in range(N):
    add(x[v][:])
    for a in range(M+1):
        xa=x[v][a]
        for b in range(a+1,M+1): add([-xa,-x[v][b]])
# at most one vertex per label
for l in range(M+1):
    for u in range(N):
        xu=x[u][l]
        for v in range(u+1,N): add([-xu,-x[v][l]])
# exactly one diff per edge
for e in range(E):
    add([z[e][d] for d in range(1,M+1)])
    for d1 in range(1,M+1):
        zd=z[e][d1]
        for d2 in range(d1+1,M+1): add([-zd,-z[e][d2]])
# exactly one edge per diff (at least/at most)
for d in range(1,M+1):
    add([z[e][d] for e in range(E)])
    for e1 in range(E):
        ze=z[e1][d]
        for e2 in range(e1+1,E): add([-ze,-z[e2][d]])
print('base clauses', clauses)
# Linking: if edge assigned d, endpoints cannot have label pair not diff d
for e,(u,v) in enumerate(edges):
    for d in range(1,M+1):
        zd=z[e][d]
        for lu in range(M+1):
            xu=x[u][lu]
            # invalid lv except lu+-d in bounds
            for lv in range(M+1):
                if abs(lu-lv)!=d:
                    add([-zd,-xu,-x[v][lv]])
print('total clauses', clauses)
# Symmetry: complement break: label(0?) not good. Add label 0 vertex index < label39 vertex index. For any u>=v? if u label0 and v label39 and u>v forbidden.
for u in range(N):
    for v in range(u+1):
        add([-x[u][0], -x[v][39]])
# Column perm sort first clique: X0<X1<X2. clauses forbidding x0=a,x1=b with a>=b; x1>=x2
for a in range(M+1):
    for b in range(a+1):
        add([-x[0][a], -x[1][b]])
        add([-x[1][a], -x[2][b]])
print('with sym clauses', clauses)
print('solve...')
sat=solver.solve()
print('sat', sat)
if sat:
    model=set(solver.get_model())
    sol=[]
    for v in range(N):
        labs=[l for l in range(M+1) if x[v][l] in model]
        sol.append(labs[0])
    print(sol)
    diffs=[abs(sol[u]-sol[v]) for u,v in edges]
    print(len(set(diffs)), sorted(diffs))
else:
    print('unsat?')
solver.delete()
